  await check('GD-01','完整目录与13类协议逐项真实渲染',async()=>{
   await open();eq(await state(()=>window.LunaGuidedConfig.catalog),catalog,'generated browser catalog exactly matches independent JSON');
   eq(catalog.services.length,25,'25 catalog services');eq(catalog.services.filter(s=>s.kind==='http').length,21,'21 HTTP catalog services');eq(catalog.services.filter(s=>s.kind==='offline').length,4,'4 native catalog services');
   const protocols=[...new Set(catalog.services.filter(s=>s.kind==='http').map(s=>s.protocol_id))].sort();eq(protocols.length,13,'13 distinct protocol identities');
   const metadata=await state(()=>window.LunaGuidedProtocolMetadata);ok(Array.isArray(metadata),'browser protocol metadata exists');for(const id of protocols)ok(metadata.some(p=>p.id===id),'protocol metadata: '+id);
   // The metadata must originate in the independent registry, not a parallel handwritten list.
   eq(metadata,registry.protocols,'protocol metadata comes unchanged from independent registry');
   const rendered=[];
   for(const service of catalog.services){
    await add(service.id);const r=await resource();rendered.push(service.id);
    eq(r.guided.serviceId,service.id,'resource keeps exact service identity');
    eq(await editor().locator('.guided-fields>[data-guided-field-row]').evaluateAll(nodes=>nodes.map(n=>n.dataset.guidedFieldRow)),mainFields(service,r.guided.values),'main fields derive from independent catalog: '+service.id);
    eq(await editor().locator('.guided-fields [data-guided-field=purpose]').count(),0,'purpose is not repeated in necessary form');
    eq(await editor().locator('[data-flat-disclosure=guided-advanced]').evaluate(n=>n.open),false,'advanced defaults closed');
    for(const f of service.fields.filter(f=>f.classification==='notapplicable'||f.ui_group==='internal'))eq(await editor().locator('[data-guided-field="'+f.id+'"]').count(),0,'internal/inapplicable input absent: '+service.id+'/'+f.id);
    for(const f of service.fields.filter(f=>f.ui_group==='purpose'))eq(await gfield(f.id).count(),0,'purpose strategy is not exposed as a resource field: '+service.id+'/'+f.id);
    for(const f of service.fields.filter(f=>f.type==='secret'&&matches(f.condition,r.guided.values)&&f.classification!=='notapplicable'))eq(await gfield(f.id).getAttribute('type'),'password','secret is visibly masked: '+service.id+'/'+f.id);
    await capture('GD-01-'+service.id.replace(/[^a-z0-9-]/gi,'-'),'#settings-window');
   }
   eq(rendered,catalog.services.map(s=>s.id),'all service identities were opened through actual catalog controls');report.catalog_coverage={services:rendered,protocols};
  });

